mapper.select:
SELECT i.* FROM t_media_item i LEFT JOIN t_file_node f ON f.id = i.file_node_id LEFT JOIN t_media_metadata m ON m.id = i.metadata_id WHERE i.user_id = #{userId} AND i.item_type = #{itemType}
AND i.directory_id = #{directoryId}
AND ( f.name ILIKE CONCAT('%', #{keyword}, '%') OR m.title ILIKE CONCAT('%', #{keyword}, '%') OR m.original_title ILIKE CONCAT('%', #{keyword}, '%') OR m.overview ILIKE CONCAT('%', #{keyword}, '%') )
ORDER BY m.release_date ASC NULLS LAST, i.id ORDER BY m.release_date DESC NULLS LAST, i.id
ORDER BY i.file_last_modified ASC NULLS LAST, i.id ORDER BY i.file_last_modified DESC NULLS LAST, i.id
